"""Export reference data for src/engine/secrets.ts, generated by the Python implementation."""

import json
import logging
import stat
import tempfile
from pathlib import Path

from ffpr_common.secrets import MissingSecret, Secrets, parse_env_file, store

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "test" / "fixtures" / "secrets.json"

parse_cases = [
    {
        "name": "comments, quotes, and a line without =",
        "text": '# comment\n\nA = "abc123"\nB=7656\nnot a pair\n',
    },
    {
        "name": "single quotes and empty value",
        "text": "A='x y'\nB=\n",
    },
]

with tempfile.TemporaryDirectory() as directory:
    tmp = Path(directory)
    secrets_file = tmp / "secrets.env"
    secrets_file.write_text("A=from_file\nB=only_file\n", encoding="utf-8")
    secrets_file.chmod(0o600)
    secrets = Secrets.load(secrets_file, environ={"A": "from_env"})
    try:
        secrets.get("C")
        missing = None
    except MissingSecret as exc:
        missing = {
            "name": exc.name,
            "path": str(exc.path).replace(str(tmp), "<tmp>"),
            "text": str(exc).replace(str(tmp), "<tmp>"),
        }

    wide = tmp / "wide.env"
    wide.write_text("KEY=value\n", encoding="utf-8")
    wide.chmod(0o644)
    records: list[str] = []

    class Capture(logging.Handler):
        def emit(self, record: logging.LogRecord) -> None:
            records.append(record.getMessage())

    handler = Capture()
    logger = logging.getLogger("ffpr_common.secrets")
    logger.addHandler(handler)
    logger.setLevel(logging.WARNING)
    try:
        Secrets.load(wide, environ={})
    finally:
        logger.removeHandler(handler)

    stored = tmp / "stored.env"
    stored.write_text("# 注释\nDEEPSEEK_API_KEY=sk-one\nBRIDGE_TOKEN=old\n", encoding="utf-8")
    store(stored, "BRIDGE_TOKEN", "new-token")
    store(stored, "STEAM_ID64", "7656")
    stored_text = stored.read_text(encoding="utf-8")
    stored_mode = stat.S_IMODE(stored.stat().st_mode)

out = {
    "parse_env_file": [
        {"name": case["name"], "text": case["text"], "expected": parse_env_file(case["text"])}
        for case in parse_cases
    ],
    "env_wins": {
        "a": secrets.get("A"),
        "b": secrets.get("B"),
        "has_c": secrets.has("C"),
    },
    "missing": missing,
    "warning": [
        {
            "mentions_file": str(wide) in message,
            "mentions_chmod": "chmod 600" in message,
        }
        for message in records
    ],
    "store": {"text": stored_text, "mode": stored_mode},
}

OUT.write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
print(f"wrote {OUT}")
